@dataclass(frozen=True)
class HornScribeProject:
    """Root persisted object for ``schemaVersion`` 1."""

    schema_version: int
    project_id: ProjectId
    source_audio: SourceAudioRef | None = None
    transcription: TranscriptionRecord | None = None
    score: ScoreRef | None = None
    user_edits: tuple[UserEdit, ...] = ()
    review_decisions: tuple[ReviewDecision, ...] = ()
    ui_session: dict[str, Any] | None = None  # optional, non-authoritative

    def to_dict(self) -> dict[str, Any]:
        return {
            "schemaVersion": self.schema_version,
            "projectId": str(self.project_id),
            "sourceAudio": self.source_audio.to_dict() if self.source_audio else None,
            "transcription": self.transcription.to_dict() if self.transcription else None,
            "score": self.score.to_dict() if self.score else None,
            "userEdits": [e.to_dict() for e in self.user_edits],
            "reviewDecisions": [d.to_dict() for d in self.review_decisions],
            "uiSession": self.ui_session,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> HornScribeProject:
        if not isinstance(data, dict):
            raise ProjectValidationError("project document is not an object")
        version = data.get("schemaVersion")
        if version is None:
            raise SchemaVersionError("missing required field: schemaVersion")
        if not isinstance(version, int):
            raise SchemaVersionError(f"schemaVersion must be an integer, got {version!r}")
        if version != SCHEMA_VERSION:
            raise SchemaVersionError(
                f"unsupported schemaVersion {version}; this build supports {SCHEMA_VERSION}"
            )
        project_id = data.get("projectId")
        if not isinstance(project_id, str) or not is_project_id(project_id):
            raise ProjectValidationError("projectId is missing or malformed")
        _validate_ids(data)
        return cls(
            schema_version=version,
            project_id=ProjectId(project_id),
            source_audio=(
                SourceAudioRef.from_dict(data["sourceAudio"]) if data.get("sourceAudio") else None
            ),
            transcription=(
                TranscriptionRecord.from_dict(data["transcription"])
                if data.get("transcription")
                else None
            ),
            score=ScoreRef.from_dict(data["score"]) if data.get("score") else None,
            user_edits=tuple(UserEdit.from_dict(e) for e in data.get("userEdits", ())),
            review_decisions=tuple(
                ReviewDecision.from_dict(d) for d in data.get("reviewDecisions", ())
            ),
            ui_session=data.get("uiSession"),
        )


def _validate_ids(data: dict[str, Any]) -> None:
    transcription = data.get("transcription")
    if transcription and not is_transcription_revision_id(transcription.get("revision", "")):
        raise ProjectValidationError("transcription.revision is malformed")
    score = data.get("score")
    if score and not is_score_revision_id(score.get("revision", "")):
        raise ProjectValidationError("score.revision is malformed")
    for edit in data.get("userEdits", ()):
        if not is_score_revision_id(edit.get("scoreRevision", "")):
            raise ProjectValidationError("userEdits[].scoreRevision is malformed")
        for note_id in edit.get("targetNoteIds", ()):
            if not is_score_note_id(note_id):
                raise ProjectValidationError("userEdits[].targetNoteIds contains malformed ID")
    for decision in data.get("reviewDecisions", ()):
        if not is_score_revision_id(decision.get("scoreRevision", "")):
            raise ProjectValidationError("reviewDecisions[].scoreRevision is malformed")

"""Project file IO: atomic writes, recovery snapshot, source relink (FND-001).

Write protocol
--------------
1. Serialize to ``<name>.tmp`` in the same directory.
2. fsync, then ``os.replace`` onto the target (atomic on Windows + POSIX).
3. Keep the previous good file as ``<name>.recovery`` before replacing —
   exactly one recovery snapshot, per plan.
"""

from __future__ import annotations

import json
import os
from dataclasses import replace
from pathlib import Path
from typing import Any

from hornscribe.project.errors import (
    ProjectValidationError,
    SourceAudioHashMismatchError,
    SourceAudioMissingError,
)
from hornscribe.project.model import HornScribeProject, hash_file_sha256

RECOVERY_SUFFIX = ".recovery"
TMP_SUFFIX = ".tmp"


def _atomic_write_json(path: Path, payload: dict[str, Any]) -> None:
    tmp = path.with_name(path.name + TMP_SUFFIX)
    blob = json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True)
    with tmp.open("w", encoding="utf-8", newline="\n") as handle:
        handle.write(blob)
        handle.flush()
        os.fsync(handle.fileno())
    if path.exists():
        recovery = path.with_name(path.name + RECOVERY_SUFFIX)
        os.replace(path, recovery)
    os.replace(tmp, path)


class ProjectStore:
    """Load/save HornScribe project files with corruption-safe semantics."""

    def __init__(self, root: Path) -> None:
        self.root = root

    def save(self, project: HornScribeProject, path: Path) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        _atomic_write_json(path, project.to_dict())

    def load(self, path: Path) -> HornScribeProject:
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            recovery = path.with_name(path.name + RECOVERY_SUFFIX)
            if recovery.exists():
                data = json.loads(recovery.read_text(encoding="utf-8"))
            else:
                raise ProjectValidationError(f"unreadable project file {path}: {exc}") from exc
        return HornScribeProject.from_dict(data)

    def relink_source_audio(self, project: HornScribeProject, path: Path) -> HornScribeProject:
        """Return a project whose sourceAudio.originalPath points at *path*.

        The candidate file must hash to the recorded content hash; audio
        identity is content, not location.
        """
        if project.source_audio is None:
            raise SourceAudioMissingError("project has no sourceAudio to relink")
        if not path.is_file():
            raise SourceAudioMissingError(f"relink candidate not found: {path}")
        actual = hash_file_sha256(path)
        if actual != project.source_audio.content_hash:
            raise SourceAudioHashMismatchError(
                f"{path} hashes to {actual}, expected {project.source_audio.content_hash}"
            )
        return replace(
            project, source_audio=replace(project.source_audio, original_path=str(path))
        )

    def verify_source_audio(self, project: HornScribeProject) -> Path:
        """Resolve the recorded source path and verify content identity."""
        if project.source_audio is None:
            raise SourceAudioMissingError("project has no sourceAudio")
        path = Path(project.source_audio.original_path)
        if not path.is_file():
            raise SourceAudioMissingError(f"source audio missing: {path}")
        if hash_file_sha256(path) != project.source_audio.content_hash:
            raise SourceAudioHashMismatchError(f"source audio changed on disk: {path}")
        return path
